mapper.select:
		/** TermsSearchMapper.countByTitle */
		SELECT
            COUNT(TERMS_ID)
        FROM
            TERMS
        WHERE
            TITLE = #{title}


            AND TERMS_ID <> #{termsId}

		/** TermsSearchMapper.countByOrderNo */
		SELECT
            COUNT(TERMS_ID)
        FROM
            TERMS
        WHERE
            USE_YN = 'Y'
            AND ORDER_NO = #{orderNo}


            AND TERMS_ID <> #{termsId}
